package org.jworkflow.outbox;
import org.jworkflow.persistence.*;import java.util.Objects;
public final class OutboxRepublishingService {private final OutboxRepository repository;private final WorkflowTransactionManager transactions;public OutboxRepublishingService(OutboxRepository repository,WorkflowTransactionManager transactions){this.repository=Objects.requireNonNull(repository);this.transactions=Objects.requireNonNull(transactions);}public OutboxMessage republish(RepublishOutboxMessageCommand command){return transactions.inTransaction(()->{OutboxMessage current=repository.findById(command.messageId()).orElseThrow(()->new OutboxRepublishException("Outbox message not found: "+command.messageId()));if(current.status()!=OutboxMessageStatus.DEAD_LETTER&&current.status()!=OutboxMessageStatus.RETRY_SCHEDULED)throw new OutboxRepublishException("Outbox message cannot be republished from "+current.status());repository.requestRepublishing(current.messageId(),command.requestedAt());return repository.findById(current.messageId()).orElseThrow();});}}
